#include <algorithm>
#include <array>
#include <fstream>
#include <iostream>
#include <map>
#include <string>
using namespace std;
void solve(istream& in, ostream& out) {
    int n; in >> n;
    map<array<string, 3>, int> frequency;
    int answer = 0;
    for (int i = 0; i < n; ++i) {
        array<string, 3> group;
        for (int j = 0; j < 3; ++j) in >> group[j];
        sort(group.begin(), group.end());
        answer = max(answer, ++frequency[group]);
    }
    out << answer << '\n';
}
int main() {
    ifstream in("records.in");
    ofstream out("records.out");
    solve(in, out);
    return 0;
}
