#include <algorithm>
#include <fstream>
#include <iostream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n; in >> n;
    vector<long long> position(n);
    for (int i = 0; i < n; ++i) in >> position[i];
    sort(position.begin(), position.end());
    long long answer = 0;
    for (int i = 0; i + 2 < n; ++i) {
        int left = i + 2, right = i + 2;
        for (int j = i + 1; j + 1 < n; ++j) {
            long long lower = 2 * position[j] - position[i];
            long long upper = 3 * position[j] - 2 * position[i];
            while (left < n && position[left] < lower) ++left;
            right = max(right, left);
            while (right < n && position[right] <= upper) ++right;
            answer += right - left;
        }
    }
    out << answer << '\n';
}
int main() {
    ifstream in("baseball.in");
    ofstream out("baseball.out");
    solve(in, out);
    return 0;
}
