**C++11 / C++17 implementation.** Read `wormhole.in` and write `wormhole.out` for this historical contest.

```cpp
#include <fstream>
#include <iostream>
#include <vector>
using namespace std;
struct Point { long long x, y; };
struct PairingCounter {
    int n;
    vector<Point> points;
    vector<int> mate, next_right;
    bool has_cycle() const {
        for (int start = 0; start < n; ++start) {
            int exit = start;
            for (int steps = 0; steps < n && exit != -1; ++steps) {
                int entry = next_right[exit];
                exit = entry == -1 ? -1 : mate[entry];
            }
            if (exit != -1) return true;
        }
        return false;
    }
    int count() {
        int first = 0;
        while (first < n && mate[first] != -1) ++first;
        if (first == n) return has_cycle() ? 1 : 0;
        int answer = 0;
        for (int other = first + 1; other < n; ++other) {
            if (mate[other] != -1) continue;
            mate[first] = other;
            mate[other] = first;
            answer += count();
            mate[first] = mate[other] = -1;
        }
        return answer;
    }
};
void solve(istream& in, ostream& out) {
    PairingCounter counter;
    in >> counter.n;
    counter.points.resize(counter.n);
    counter.mate.assign(counter.n, -1);
    counter.next_right.assign(counter.n, -1);
    for (int i = 0; i < counter.n; ++i) in >> counter.points[i].x >> counter.points[i].y;
    for (int i = 0; i < counter.n; ++i) {
        for (int j = 0; j < counter.n; ++j) {
            if (counter.points[j].y != counter.points[i].y
                || counter.points[j].x <= counter.points[i].x) continue;
            int nearest = counter.next_right[i];
            if (nearest == -1 || counter.points[j].x < counter.points[nearest].x)
                counter.next_right[i] = j;
        }
    }
    out << counter.count() << '\n';
}
int main() {
    ifstream in("wormhole.in");
    ofstream out("wormhole.out");
    solve(in, out);
    return 0;
}
